"""Independent verification of a version-3 result against its epoch."""
import sys
from fractions import Fraction

sys.path.insert(0, '/workspace/vendor')
sys.path.insert(0, '/workspace/submission')

import testcnnonnx
import testrnnonnx
from probability import window_thresholds

_THS = None


def predict(model, features):
    if not features:
        return []
    labels = [0] * len(features)
    if model == 'cnn':
        return testcnnonnx.evaluate_model_single_pass(features, labels)
    return testrnnonnx.evaluate_model_single_pass(features, labels)


def geometry(case):
    S = len(case['slots']); J = len(case['windows'])
    F = len(case['flows']); G = len(case['groups'])
    a = [2 + 3 * s for s in range(S)]
    b = [3 + 3 * s for s in range(S)]
    e = [4 + 3 * s for s in range(S)]
    w = [2 + 3 * S + j for j in range(J)]
    z = [2 + 3 * S + J + f for f in range(F)]
    h = [2 + 3 * S + J + F + g for g in range(G)]
    return dict(S=S, J=J, F=F, G=G, a=a, b=b, e=e, w=w, z=z, h=h,
                K=2 + 3 * S + J + F + G)


def eligible(case, ths, j, s):
    window = case['windows'][j]
    times = [slot[0] for slot in case['slots']]
    return window[5] < ths[j] and window[1] <= times[s] <= window[2]


def protocol_arcs(case, values, lower, geom, ths):
    S, J, F, G = geom['S'], geom['J'], geom['F'], geom['G']
    slots = case['slots']
    times = [s[0] for s in slots]
    R, Z = 0, 1
    a, b, e, w, z, h = geom['a'], geom['b'], geom['e'], geom['w'], geom['z'], geom['h']
    B, I = case['bucket']
    W = 1 + J * times[-1]
    arcs = []
    tags = []
    for s in range(S):
        arcs.append((R, a[s], 0, I if s == 0 else slots[s][2], 0)); tags.append(('R_a', s))
        arcs.append((a[s], b[s], 0, B, 0)); tags.append(('a_b', s))
        if s + 1 < S:
            arcs.append((b[s], a[s + 1], 0, B, 0)); tags.append(('b_a', s))
        arcs.append((b[s], e[s], 0, slots[s][1], 0)); tags.append(('b_e', s))
    for s in range(S):
        for j in range(J):
            if eligible(case, ths, j, s):
                cost = (times[s] - case['windows'][j][1]) - values[j] * W
                arcs.append((e[s], w[j], 0, 1, cost)); tags.append(('pair', s, j))
    for j in range(J):
        arcs.append((w[j], z[case['windows'][j][0]], 0, 1, 0)); tags.append(('w_z', j))
    for f in range(F):
        group = case['flows'][f][2]
        head = Z if group == -1 else h[group]
        arcs.append((z[f], head, lower[f], case['flows'][f][1], 0)); tags.append(('z_out', f))
    for g in range(G):
        parent = case['groups'][g][0]
        head = Z if parent == -1 else h[parent]
        arcs.append((h[g], head, 0, case['groups'][g][1], 0)); tags.append(('h_out', g))
    arcs.append((Z, R, 0, J, 0)); tags.append(('Z_R',))
    return arcs, tags


def ceil_frac(ratio, target):
    num = ratio.numerator * target
    den = ratio.denominator
    return -((-num) // den)


def check(case, result):
    errors = []
    geom = geometry(case)
    S, J, F, G = geom['S'], geom['J'], geom['F'], geom['G']
    slots = case['slots']
    times = [s[0] for s in slots]
    windows = case['windows']
    flows = case['flows']
    groups = case['groups']

    preds = predict(case['model'], [w[7] for w in windows])
    ths = window_thresholds(case['stats'], windows)
    values = [windows[j][6] * case['class_values'][preds[j]] for j in range(J)]
    W = 1 + J * times[-1]

    if result['predictions'] != [int(p) for p in preds]:
        errors.append('predictions')
    if result['thresholds'] != [int(t) for t in ths]:
        errors.append('thresholds')

    assignment = result['assignment']
    if len(assignment) != J:
        return errors + ['assignment length']

    counts = [0] * F
    per_slot = [0] * S
    for j in range(J):
        slot = assignment[j]
        if slot == -1:
            continue
        if not (0 <= slot < S):
            return errors + ['assignment slot range']
        window = windows[j]
        if not (window[5] < ths[j]):
            errors.append('window %d fails gate' % j)
        if not (window[1] <= times[slot] <= window[2]):
            errors.append('window %d outside window' % j)
        counts[window[0]] += 1
        per_slot[slot] += 1
    for s in range(S):
        if per_slot[s] > slots[s][1]:
            errors.append('slot %d capacity' % s)
    for f in range(F):
        if counts[f] > flows[f][1]:
            errors.append('flow %d ceiling' % f)
    for g in range(G):
        total = 0
        stack = [g]
        seen = set()
        while stack:
            node = stack.pop()
            if node in seen:
                continue
            seen.add(node)
            for f in range(F):
                if flows[f][2] == node:
                    total += counts[f]
            for g2 in range(G):
                if groups[g2][0] == node:
                    stack.append(g2)
        if total > groups[g][1]:
            errors.append('group %d ceiling (%d > %d)' % (g, total, groups[g][1]))
    B, I = case['bucket']
    carry = I
    for s in range(S):
        if s == 0:
            available = I
        else:
            available = min(B, carry + slots[s][2])
        if per_slot[s] > available:
            errors.append('slot %d tokens (%d > %d)' % (s, per_slot[s], available))
        carry = available - per_slot[s]

    utility = 0
    age = 0
    for j in range(J):
        if assignment[j] >= 0:
            utility += values[j]
            age += times[assignment[j]] - windows[j][1]
    if result['utility'] != utility:
        errors.append('utility %r != %r' % (result['utility'], utility))
    if result['age'] != age:
        errors.append('age %r != %r' % (result['age'], age))
    ratio = Fraction(1)
    for f in range(F):
        value = Fraction(counts[f], flows[f][0])
        if value < ratio:
            ratio = value
    p, q = result['ratio']
    if Fraction(p, q) != ratio:
        errors.append('ratio %r != %r' % (result['ratio'], ratio))
    if not (0 <= p <= q <= 64 and q >= 1):
        errors.append('ratio bounds')

    lower = [ceil_frac(ratio, flows[f][0]) for f in range(F)]
    arcs, tags = protocol_arcs(case, values, lower, geom, ths)
    if len(result['flow']) != len(arcs):
        return errors + ['flow length %d != %d' % (len(result['flow']), len(arcs))]
    balance = {}
    for (u, v, l, h, c), x in zip(arcs, result['flow']):
        if not (l <= x <= h):
            errors.append('arc %s flow %d outside [%d,%d]' % (tags, x, l, h))
        balance[u] = balance.get(u, 0) - x
        balance[v] = balance.get(v, 0) + x
    for node, value in balance.items():
        if value != 0:
            errors.append('conservation at node %d: %d' % (node, value))
    for tag, (u, v, l, h, c), x in zip(tags, arcs, result['flow']):
        if tag[0] == 'pair':
            s, j = tag[1], tag[2]
            want = 1 if assignment[j] == s else 0
            if x != want:
                errors.append('pair arc (%d,%d) flow %d != %d' % (s, j, x, want))

    pot = result['potential']
    if len(pot) != geom['K']:
        return errors + ['potential length']
    for value in pot:
        if abs(value) > 10 ** 60:
            errors.append('potential magnitude')
    for tag, (u, v, l, h, c), x in zip(tags, arcs, result['flow']):
        if x < h and c + pot[u] - pot[v] < 0:
            errors.append('potential forward %s' % (tag,))
        if x > l and -c + pot[v] - pot[u] < 0:
            errors.append('potential backward %s' % (tag,))

    if ratio >= 1:
        if result['cut'] is not None:
            errors.append('cut must be null at full coverage')
    else:
        cands = sorted({Fraction(k, flows[f][0]) for f in range(F)
                        for k in range(flows[f][0] + 1)})
        nxt = None
        for value in cands:
            if value > ratio:
                nxt = value
                break
        if nxt is None:
            errors.append('no next ratio')
        else:
            lower2 = [ceil_frac(nxt, flows[f][0]) for f in range(F)]
            arcs2, _ = protocol_arcs(case, values, lower2, geom, ths)
            cut = result['cut']
            if cut is None:
                errors.append('cut missing')
            else:
                if len(set(cut)) != len(cut):
                    errors.append('cut duplicates')
                if any(not (0 <= node < geom['K']) for node in cut):
                    errors.append('cut node range')
                if any(type(node) is not int for node in cut):
                    errors.append('cut node type')
                inside = set(cut)
                entering = 0
                leaving = 0
                for (u, v, l, h, c) in arcs2:
                    if u not in inside and v in inside:
                        entering += l
                    if u in inside and v not in inside:
                        leaving += h
                if not entering > leaving:
                    errors.append('cut not infeasible: %d <= %d' % (entering, leaving))
    return errors


def check_reports(case, result, errors):
    import metrics
    report = metrics.selected_report(case['flows'], case['windows'],
                                     result['predictions'], result['assignment'])
    got = result['reports']
    for level in ('packet', 'stream'):
        for key in ('accuracy', 'macro_precision', 'macro_recall', 'macro_f1'):
            if abs(got[level][key] - report[level][key]) > 1e-12:
                errors.append('report %s %s' % (level, key))
        if got[level]['confusion'] != report[level]['confusion']:
            errors.append('report %s confusion' % level)
    return errors
